// V132-street: CC0 street furniture from Poly Haven (polyhaven.com, CC0 1.0): fire_hydrant, metal_trash_can, street_lamp_01,
// utility_box_01/02 (painted_wooden_bench tried and rejected: reads as an indoor table-bench). Built by tools/street132_assets.mjs: non-variant nodes merged, meshoptimizer-simplified to
// ~300-750 tris, diffuse 1k -> 128px 5-bit (assets/l11-v132st). Geometry is embedded so the synchronous street builders can use it.
// Off: ?st132=0 or localStorage bumpercrop.st132=0 (old procedural props).
import * as T from './vendor/three.module.min.js';
const GEO={"hydrant":{"body":{"v":"","i":"","tris":648}},"trashcan":{"body":{"v":"","i":"","tris":416}},"lamp":{"body":{"v":"","i":"","tris":744},"glass":{"v":"","i":"","tris":40}},"ubox1":{"body":{"v":"","i":"","tris":499}},"ubox2":{"body":{"v":"","i":"","tris":700}}};
export const ST132_ON=(()=>{try{if(/[?&]st132=0/.test(location.search))return false;if(localStorage.getItem('bumpercrop.st132')==='0')return false;}catch(e){}return true;})();
const A=new URL('./assets/l11-v132st/',import.meta.url).href,b64=s=>{const r=atob(s),u=new Uint8Array(r.length);for(let i=0;i<r.length;i++)u[i]=r.charCodeAt(i);return u.buffer;};
const cache=new Map();
function geo(name,part){const k=name+'/'+part;if(cache.has(k))return cache.get(k);const d=GEO[name][part],v=new Float32Array(b64(d.v)),i=new Uint16Array(b64(d.i)),n=v.length/8;
 const p=new Float32Array(n*3),nn=new Float32Array(n*3),uv=new Float32Array(n*2);for(let j=0;j<n;j++){p.set(v.subarray(j*8,j*8+3),j*3);nn.set(v.subarray(j*8+3,j*8+6),j*3);uv[j*2]=v[j*8+6];uv[j*2+1]=v[j*8+7];}
 const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(p,3));g.setAttribute('normal',new T.BufferAttribute(nn,3));g.setAttribute('uv',new T.BufferAttribute(uv,2));g.setIndex(new T.BufferAttribute(i,1));cache.set(k,g);return g;}
function mat(b,name){const key='st132:'+name;if(!b.mats[key]){const t=new T.TextureLoader().load(A+name+'.webp?v=132');t.colorSpace=T.SRGBColorSpace;t.flipY=false;t.magFilter=T.NearestFilter;t.anisotropy=2;
 b.mats[key]=new T.MeshStandardMaterial({map:t,roughness:.8,metalness:0,vertexColors:true});b.mats[key].name='V132 '+name+' (Poly Haven CC0)';}return key;}
function put(b,name,x=0,y=0,z=0,s=1,sy=s,ry=0,tone=1){b.add(geo(name,'body'),mat(b,name),x,y,z,s,sy,s,ry,0,0,tone);if(GEO[name].glass)b.add(geo(name,'glass'),'lamp',x,y,z,s,sy,s,ry,0,0,1);}
export function hydrant132(b){put(b,'hydrant',0,0,0,1.15,1.05,Math.PI/2);b.circle(0,0,.27);}
export function trashcan132(b){put(b,'trashcan',0,0,0,.95);b.circle(0,0,.30);}
export function lantern132(b,{height=4.2}={}){const s=height/3.85;b.cylinder('concrete',0,.02,0,.26,.28,.04,10,0,0,.85);put(b,'lamp',0,0,0,s,s);b.circle(0,0,.2);}
export function ubox132(b,{variant=0}={}){const green=variant%2===1,w=green?.76:.58,d=green?.43:.36;b.box('concrete',0,.055,0,w+.13,.11,d+.13,0,.80);
 if(green)put(b,'ubox2',0,.11,0,w/.92,1.32/1.12);else put(b,'ubox1',0,.11,0,w/.52,1.08/1.09);b.solid(0,0,w+.12,d+.12);}
const PI=Math.PI;
